ENV_FILE="${ENV_FILE:-$HOME/.config/solana/mgk-provision.env}"

banner "MGK devnet provisioning (issue #17, free tier)"

# Already done by the agent (pubkeys are public, safe to show):
#   keeper  FnuTgyBSp7wmvymWEFEQafYfqsgUZEXd8YxP5SWWkm2  (0.5 SOL)
#   oracle  72dFyhGoA5uNep2XFTv4saMJVPecSNcthXZkaquUXHue  (0.5 SOL)
